/* Public API of the compression engine used by the command line tool. */
#ifndef XZR_H
#define XZR_H

#include "common/common.h"
#include "common/check.h"
#include "common/filter.h"

/* ---------------------------------------------------------------- */
/* Decoder flags                                                      */
/* ---------------------------------------------------------------- */
#define XR_TELL_NO_CHECK          UINT32_C(0x01)
#define XR_TELL_UNSUPPORTED_CHECK UINT32_C(0x02)
#define XR_TELL_ANY_CHECK         UINT32_C(0x04)
#define XR_IGNORE_CHECK           UINT32_C(0x10)
#define XR_CONCATENATED           UINT32_C(0x08)
#define XR_FAIL_FAST              UINT32_C(0x20)

/* ---------------------------------------------------------------- */
/* Stream and block structures                                        */
/* ---------------------------------------------------------------- */
typedef struct {
	uint32_t version;
	xr_vli backward_size;
	uint32_t check;
} xr_stream_flags;

#define XR_BACKWARD_SIZE_MIN 4
#define XR_BACKWARD_SIZE_MAX (UINT64_C(1) << 34)

typedef struct {
	uint32_t version;
	uint32_t header_size;
	uint32_t check;
	xr_vli compressed_size;
	xr_vli uncompressed_size;
	xr_filter *filters;
	uint8_t raw_check[XR_CHECK_SIZE_MAX];
	void *reserved_ptr1;
	xr_vli reserved_vli1;
	bool ignore_check;
} xr_block;

/* Computes the encoded size of a block header for the given block. */
xr_ret xr_block_header_size(xr_block *block);
xr_ret xr_block_header_encode(const xr_block *block, uint8_t *out);
xr_ret xr_block_header_decode(xr_block *block, const uint8_t *in);
/* Size of the block header in bytes given the first byte. */
static inline uint32_t xr_block_header_size_decode(uint8_t b)
{
	return ((uint32_t)b + 1) * 4;
}

xr_ret xr_block_compressed_size(xr_block *block, xr_vli unpadded_size);
xr_vli xr_block_unpadded_size(const xr_block *block);
xr_vli xr_block_total_size(const xr_block *block);

xr_ret xr_stream_header_encode(const xr_stream_flags *options, uint8_t *out);
xr_ret xr_stream_header_decode(xr_stream_flags *options, const uint8_t *in);
xr_ret xr_stream_footer_encode(const xr_stream_flags *options, uint8_t *out);
xr_ret xr_stream_footer_decode(xr_stream_flags *options, const uint8_t *in);
xr_ret xr_stream_flags_compare(const xr_stream_flags *a,
		const xr_stream_flags *b);

extern const uint8_t XR_HEADER_MAGIC[6];
extern const uint8_t XR_FOOTER_MAGIC[2];

/* ---------------------------------------------------------------- */
/* Index                                                              */
/* ---------------------------------------------------------------- */
typedef struct xr_index xr_index;

typedef struct {
	struct {
		const xr_stream_flags *flags;
		const void *r1, *r2, *r3;
		xr_vli number;
		xr_vli block_count;
		xr_vli compressed_offset;
		xr_vli uncompressed_offset;
		xr_vli compressed_size;
		xr_vli uncompressed_size;
		xr_vli padding;
	} stream;

	struct {
		xr_vli number_in_file;
		xr_vli compressed_file_offset;
		xr_vli uncompressed_file_offset;
		xr_vli number_in_stream;
		xr_vli compressed_stream_offset;
		xr_vli uncompressed_stream_offset;
		xr_vli uncompressed_size;
		xr_vli unpadded_size;
		xr_vli total_size;
	} block;

	/* Internal iterator state */
	const void *internal[6];
} xr_index_iter;

typedef enum {
	XR_INDEX_ITER_ANY = 0,
	XR_INDEX_ITER_STREAM = 1,
	XR_INDEX_ITER_BLOCK = 2,
	XR_INDEX_ITER_NONEMPTY_BLOCK = 3
} xr_index_iter_mode;

xr_index *xr_index_init(void);
void xr_index_end(xr_index *i);
xr_ret xr_index_append(xr_index *i, xr_vli unpadded_size,
		xr_vli uncompressed_size);
xr_ret xr_index_stream_flags(xr_index *i, const xr_stream_flags *flags);
xr_ret xr_index_stream_padding(xr_index *i, xr_vli padding);
xr_vli xr_index_block_count(const xr_index *i);
xr_vli xr_index_stream_count(const xr_index *i);
xr_vli xr_index_size(const xr_index *i);
xr_vli xr_index_stream_size(const xr_index *i);
xr_vli xr_index_total_size(const xr_index *i);
xr_vli xr_index_file_size(const xr_index *i);
xr_vli xr_index_uncompressed_size(const xr_index *i);
uint32_t xr_index_checks(const xr_index *i);
uint64_t xr_index_memusage(xr_vli streams, xr_vli blocks);
uint64_t xr_index_memused(const xr_index *i);
xr_ret xr_index_cat(xr_index *dest, xr_index *src);

void xr_index_iter_init(xr_index_iter *iter, const xr_index *i);
void xr_index_iter_rewind(xr_index_iter *iter);
bool xr_index_iter_next(xr_index_iter *iter, xr_index_iter_mode mode);

xr_ret xr_index_buffer_encode(const xr_index *i, uint8_t *out,
		size_t *out_pos, size_t out_size);
xr_ret xr_index_buffer_decode(xr_index **i, uint64_t *memlimit,
		const uint8_t *in, size_t *in_pos, size_t in_size);
xr_ret xr_index_decoder(xr_stream *strm, xr_index **i, uint64_t memlimit);
xr_ret xr_index_encoder(xr_stream *strm, const xr_index *i);

/* ---------------------------------------------------------------- */
/* High level coders                                                  */
/* ---------------------------------------------------------------- */
xr_ret xr_stream_encoder(xr_stream *strm, const xr_filter *filters,
		uint32_t check);
xr_ret xr_alone_encoder(xr_stream *strm, const xr_options_lzma *options);
xr_ret xr_raw_encoder(xr_stream *strm, const xr_filter *filters);

xr_ret xr_stream_decoder(xr_stream *strm, uint64_t memlimit, uint32_t flags);
xr_ret xr_auto_decoder(xr_stream *strm, uint64_t memlimit, uint32_t flags);
xr_ret xr_alone_decoder(xr_stream *strm, uint64_t memlimit);
xr_ret xr_lzip_decoder(xr_stream *strm, uint64_t memlimit, uint32_t flags);
xr_ret xr_raw_decoder(xr_stream *strm, const xr_filter *filters);

/* Multi-threaded stream encoder. */
typedef struct {
	uint32_t flags;
	uint32_t threads;
	uint64_t block_size;
	uint32_t timeout;
	uint32_t preset;
	const xr_filter *filters;
	uint32_t check;
	uint64_t memlimit_threading;
	uint64_t memlimit_stop;
} xr_mt_options;

xr_ret xr_stream_encoder_mt(xr_stream *strm, const xr_mt_options *options);
uint64_t xr_stream_encoder_mt_memusage(const xr_mt_options *options);

typedef struct {
	uint32_t flags;
	uint32_t threads;
	uint64_t memlimit_threading;
	uint64_t memlimit_stop;
	uint32_t timeout;
} xr_mt_dec_options;

xr_ret xr_stream_decoder_mt(xr_stream *strm, const xr_mt_dec_options *options);

/* Block-level helpers used by the encoder(s). */
xr_ret xr_block_encoder_init(xr_next_coder *next, xr_block *block);
xr_ret xr_block_decoder_init(xr_next_coder *next, xr_block *block);
xr_ret xr_block_buffer_encode(xr_block *block, const uint8_t *in,
		size_t in_size, uint8_t *out, size_t *out_pos, size_t out_size);
uint64_t xr_block_buffer_bound64(uint64_t uncompressed_size);

/* Progress query used for -v. */
void xr_get_progress(xr_stream *strm, uint64_t *progress_in,
		uint64_t *progress_out);

/* Check type of the stream being decoded (for -v / --list). */
uint32_t xr_get_check(const xr_stream *strm);

/* Memory limit adjustment on an active decoder. */
uint64_t xr_memusage(const xr_stream *strm);
uint64_t xr_memlimit_get(const xr_stream *strm);
xr_ret xr_memlimit_set(xr_stream *strm, uint64_t memlimit);

/* Encoder/decoder memory usage for a filter chain. */
uint64_t xr_raw_encoder_memusage(const xr_filter *filters);
uint64_t xr_raw_decoder_memusage(const xr_filter *filters);

/* Physical memory / CPU helpers. */
uint64_t xr_physmem(void);
uint32_t xr_cputhreads(void);

/* Filter-string (--filters) support. */
xr_ret xr_str_to_filters(const char *str, int *error_pos, xr_filter *filters,
		uint32_t flags, char **error_message);
xr_ret xr_str_from_filters(char **str, const xr_filter *filters,
		uint32_t flags);
const char *xr_str_list_filters(uint32_t flags);

#define XR_STR_ALL_FILTERS  UINT32_C(0x01)
#define XR_STR_NO_VALIDATION UINT32_C(0x02)
#define XR_STR_ENCODER      UINT32_C(0x10)
#define XR_STR_DECODER      UINT32_C(0x20)
#define XR_STR_GETOPT_LONG  UINT32_C(0x40)
#define XR_STR_NO_SPACES    UINT32_C(0x80)

#endif

/* Shared declarations for the compression engine.
 *
 * This is an independent implementation of the .xz / .lzma container
 * formats and of the LZMA/LZMA2 compression algorithms.
 */
#ifndef XZR_COMMON_H
#define XZR_COMMON_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

/* ---------------------------------------------------------------- */
/* Return codes                                                       */
/* ---------------------------------------------------------------- */
typedef enum {
	XR_OK = 0,
	XR_STREAM_END = 1,
	XR_NO_CHECK = 2,
	XR_UNSUPPORTED_CHECK = 3,
	XR_GET_CHECK = 4,
	XR_MEM_ERROR = 5,
	XR_MEMLIMIT_ERROR = 6,
	XR_FORMAT_ERROR = 7,
	XR_OPTIONS_ERROR = 8,
	XR_DATA_ERROR = 9,
	XR_BUF_ERROR = 10,
	XR_PROG_ERROR = 11,
	XR_SEEK_NEEDED = 12
} xr_ret;

/* Coder actions, mirroring the streaming API style. */
typedef enum {
	XR_RUN = 0,
	XR_SYNC_FLUSH = 1,
	XR_FULL_FLUSH = 2,
	XR_FINISH = 3,
	XR_FULL_BARRIER = 4
} xr_action;

/* ---------------------------------------------------------------- */
/* Variable-length integers and limits                                */
/* ---------------------------------------------------------------- */
typedef uint64_t xr_vli;

#define XR_VLI_MAX (UINT64_MAX / 2)
#define XR_VLI_UNKNOWN UINT64_MAX
#define XR_VLI_BYTES_MAX 9

#define XR_STREAM_HEADER_SIZE 12
#define XR_BLOCK_HEADER_SIZE_MAX 1024

#define XR_CHECK_SIZE_MAX 64
#define XR_CHECK_ID_MAX 15

/* Filter identifiers (as stored in .xz block headers). */
#define XR_FILTER_X86        UINT64_C(0x04)
#define XR_FILTER_POWERPC    UINT64_C(0x05)
#define XR_FILTER_IA64       UINT64_C(0x06)
#define XR_FILTER_ARM        UINT64_C(0x07)
#define XR_FILTER_ARMTHUMB   UINT64_C(0x08)
#define XR_FILTER_SPARC      UINT64_C(0x09)
#define XR_FILTER_ARM64      UINT64_C(0x0A)
#define XR_FILTER_RISCV      UINT64_C(0x0B)
#define XR_FILTER_DELTA      UINT64_C(0x03)
#define XR_FILTER_LZMA1      UINT64_C(0x4000000000000001)
#define XR_FILTER_LZMA2      UINT64_C(0x21)
#define XR_FILTERS_MAX 4
#define XR_VLI_UNKNOWN_FILTER UINT64_MAX

/* Check types */
enum {
	XR_CHECK_NONE = 0,
	XR_CHECK_CRC32 = 1,
	XR_CHECK_CRC64 = 4,
	XR_CHECK_SHA256 = 10
};

/* Presets */
#define XR_PRESET_DEFAULT 6
#define XR_PRESET_LEVEL_MASK UINT32_C(0x1F)
#define XR_PRESET_EXTREME (UINT32_C(1) << 31)

/* LZMA option ranges */
#define XR_DICT_SIZE_MIN UINT32_C(4096)
#define XR_DICT_SIZE_MAX (UINT32_C(1) << 30)  /* 1.5 GiB handled specially */
#define XR_DICT_SIZE_DEFAULT (UINT32_C(1) << 23)

#define XR_LCLP_MIN 0
#define XR_LCLP_MAX 4
#define XR_LC_DEFAULT 3
#define XR_LP_DEFAULT 0
#define XR_PB_MIN 0
#define XR_PB_MAX 4
#define XR_PB_DEFAULT 2

typedef enum {
	XR_MODE_FAST = 1,
	XR_MODE_NORMAL = 2
} xr_mode;

typedef enum {
	XR_MF_HC3 = 0x03,
	XR_MF_HC4 = 0x04,
	XR_MF_BT2 = 0x12,
	XR_MF_BT3 = 0x13,
	XR_MF_BT4 = 0x14
} xr_match_finder;

#define XR_MATCH_LEN_MIN 2
#define XR_MATCH_LEN_MAX 273

typedef struct {
	uint32_t dict_size;
	const uint8_t *preset_dict;
	uint32_t preset_dict_size;
	uint32_t lc;
	uint32_t lp;
	uint32_t pb;
	xr_mode mode;
	uint32_t nice_len;
	xr_match_finder mf;
	uint32_t depth;
	uint32_t ext_flags;
	uint32_t ext_size_low;
	uint32_t ext_size_high;
} xr_options_lzma;

typedef struct {
	uint32_t dist;
} xr_options_delta;

typedef struct {
	uint32_t start_offset;
} xr_options_bcj;

typedef struct {
	uint64_t id;
	void *options;
} xr_filter;

/* ---------------------------------------------------------------- */
/* Generic streaming coder plumbing                                   */
/* ---------------------------------------------------------------- */
typedef struct xr_stream xr_stream;

struct xr_next_coder;

typedef xr_ret (*xr_code_fn)(void *coder, const uint8_t *restrict in,
		size_t *restrict in_pos, size_t in_size,
		uint8_t *restrict out, size_t *restrict out_pos,
		size_t out_size, xr_action action);

typedef void (*xr_end_fn)(void *coder);

typedef struct xr_next_coder {
	void *coder;
	uint64_t id;
	xr_code_fn code;
	xr_end_fn end;
	void (*get_progress)(void *coder, uint64_t *in, uint64_t *out);
	uint64_t (*memconfig)(void *coder, uint64_t *memusage,
			uint64_t *old_memlimit, uint64_t new_memlimit);
} xr_next_coder;

#define XR_NEXT_CODER_INIT ((xr_next_coder){ NULL, UINT64_MAX, NULL, NULL, NULL, NULL })

struct xr_stream {
	const uint8_t *next_in;
	size_t avail_in;
	uint64_t total_in;

	uint8_t *next_out;
	size_t avail_out;
	uint64_t total_out;

	uint64_t memlimit;

	/* Internal state */
	struct xr_internal *internal;
};

typedef struct xr_internal {
	xr_next_coder next;
	xr_action sequence_action;
	bool supported_actions[5];
	size_t avail_in;
	bool allow_buf_error;
} xr_internal;

xr_ret xr_strm_init(xr_stream *strm);
xr_ret xr_code(xr_stream *strm, xr_action action);
void xr_end(xr_stream *strm);

void xr_next_end(xr_next_coder *next);

/* ---------------------------------------------------------------- */
/* Small helpers                                                      */
/* ---------------------------------------------------------------- */
static inline uint32_t xr_read32le(const uint8_t *b)
{
	return (uint32_t)b[0] | ((uint32_t)b[1] << 8)
			| ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);
}

static inline uint64_t xr_read64le(const uint8_t *b)
{
	return (uint64_t)xr_read32le(b) | ((uint64_t)xr_read32le(b + 4) << 32);
}

static inline void xr_write32le(uint8_t *b, uint32_t v)
{
	b[0] = (uint8_t)v;
	b[1] = (uint8_t)(v >> 8);
	b[2] = (uint8_t)(v >> 16);
	b[3] = (uint8_t)(v >> 24);
}

static inline void xr_write64le(uint8_t *b, uint64_t v)
{
	xr_write32le(b, (uint32_t)v);
	xr_write32le(b + 4, (uint32_t)(v >> 32));
}

static inline uint32_t xr_read32be(const uint8_t *b)
{
	return ((uint32_t)b[0] << 24) | ((uint32_t)b[1] << 16)
			| ((uint32_t)b[2] << 8) | (uint32_t)b[3];
}

static inline void xr_write32be(uint8_t *b, uint32_t v)
{
	b[0] = (uint8_t)(v >> 24);
	b[1] = (uint8_t)(v >> 16);
	b[2] = (uint8_t)(v >> 8);
	b[3] = (uint8_t)v;
}

/* Number of bytes a VLI takes when encoded. */
static inline uint32_t xr_vli_size(xr_vli v)
{
	uint32_t n = 0;
	do {
		++n;
		v >>= 7;
	} while (v != 0);
	return n;
}

xr_ret xr_vli_encode(xr_vli vli, size_t *vli_pos, uint8_t *out,
		size_t *out_pos, size_t out_size);
xr_ret xr_vli_decode(xr_vli *vli, size_t *vli_pos, const uint8_t *in,
		size_t *in_pos, size_t in_size);

/* Buffer-to-buffer helper used by several coders. */
static inline size_t xr_bufcpy(const uint8_t *restrict in,
		size_t *restrict in_pos, size_t in_size,
		uint8_t *restrict out, size_t *restrict out_pos,
		size_t out_size)
{
	const size_t in_avail = in_size - *in_pos;
	const size_t out_avail = out_size - *out_pos;
	const size_t n = in_avail < out_avail ? in_avail : out_avail;
	memcpy(out + *out_pos, in + *in_pos, n);
	*in_pos += n;
	*out_pos += n;
	return n;
}

#define xr_min(a, b) ((a) < (b) ? (a) : (b))
#define xr_max(a, b) ((a) > (b) ? (a) : (b))

#endif

/* Integrity check abstraction (None / CRC32 / CRC64 / SHA-256). */
#ifndef XZR_CHECK_H
#define XZR_CHECK_H

#include "common.h"

typedef struct {
	uint32_t state[8];
	uint64_t size;
} xr_sha256_state;

typedef struct {
	union {
		uint8_t u8[64];
		uint32_t u32[16];
		uint64_t u64[8];
	} buffer;
	union {
		uint32_t crc32;
		uint64_t crc64;
		xr_sha256_state sha256;
	} state;
} xr_check_state;

extern const uint32_t xr_crc32_table[8][256];
extern const uint64_t xr_crc64_table[4][256];

uint32_t xr_crc32(const uint8_t *buf, size_t size, uint32_t crc);
uint64_t xr_crc64(const uint8_t *buf, size_t size, uint64_t crc);

void xr_sha256_init(xr_check_state *check);
void xr_sha256_update(const uint8_t *buf, size_t size, xr_check_state *check);
void xr_sha256_finish(xr_check_state *check);

void xr_check_init(xr_check_state *check, uint32_t type);
void xr_check_update(xr_check_state *check, uint32_t type,
		const uint8_t *buf, size_t size);
void xr_check_finish(xr_check_state *check, uint32_t type);

/* Size in bytes of the check value stored in the stream. */
extern const uint8_t xr_check_sizes[16];

static inline bool xr_check_is_supported(uint32_t type)
{
	return type == XR_CHECK_NONE || type == XR_CHECK_CRC32
			|| type == XR_CHECK_CRC64 || type == XR_CHECK_SHA256;
}

#endif
