/* Dispatcher for the integrity check types defined by the .xz format. */

#include "check.h"

/* Check sizes as listed in the .xz file format specification.  Only the
 * IDs 0 (None), 1 (CRC32), 4 (CRC64) and 10 (SHA-256) are implemented,
 * but the sizes of the reserved IDs are needed to skip over unsupported
 * check fields while decoding. */
const uint8_t xr_check_sizes[16] = {
	0,
	4, 4, 4,
	8, 8, 8,
	16, 16, 16,
	32, 32, 32,
	64, 64, 64
};

void xr_check_init(xr_check_state *check, uint32_t type)
{
	switch (type) {
	case XR_CHECK_NONE:
